[ExtensionOf(classStr(MarkupTransInsert))]
final class AVAMarkupTransInsertCls_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method skipMarkupAutoLine
/// </summary>
/// <param name = "_markupAutoLine">MarkupAutoLine</param>
/// <returns>boolean</returns>
protected boolean skipMarkupAutoLine(MarkupAutoLine _markupAutoLine)
{
    boolean ret = next skipMarkupAutoLine(_markupAutoLine);

    ret = ret 
        || this.avaMarkupAutoLineDateInvalid(_markupAutoLine)
        || this.avaMarkupAutoLinePurchAgreement(_markupAutoLine)
        || this.avaMarkupAutoLinePurchLine(_markupAutoLine);

    return ret;
}

/// <summary>
/// Skips all auto lines outside of the date range
/// </summary>
/// <param name = "_markupAutoLine">MarkupAutoLine</param>
/// <returns>boolean</returns>
public boolean avaMarkupAutoLineDateInvalid(MarkupAutoLine _markupAutoLine)
{
    TransDate avaToday = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    if ((_markupAutoLine.AVAFromDate != dateNull()
            && _markupAutoLine.AVAFromDate > avaToday)
        || (_markupAutoLine.AVAToDate != dateNull()
            && _markupAutoLine.AVAToDate < avaToday))
    {
        return true;
    }
    else
    {
        return false;
    }

}

/// <summary>
/// checks MTZ-MarkupAutoLines for vendor sources; if effective price in source is active, line gets skipped
/// </summary>
/// <param name = "_markupAutoLine">MarkupAutoLine</param>
/// <returns>boolean</returns>
public boolean avaMarkupAutoLinePurchAgreement(MarkupAutoLine _markupAutoLine)
{
    Common locCommon = this.parameters.Source;

    if(this.parameters.ModuleType != MarkupModuleType::Vend
        || _markupAutoLine.MarkupCategory != MarkupCategory::AVAMTZ)
    {
        return false;
    }

    switch(locCommon.TableId)
    {
        case tableNum(AgreementLine):
            AgreementLine locAgreementline = locCommon as AgreementLine;
            if(locAgreementLine.AVAEffectivePrice == NoYes::Yes)
            {
                return true;
            }
            break;
    }

    return false;
}

/// <summary>
/// Checks for PurchLine records if a connected AgreementLine already has a markupTrans record of the same type as the auto line and skips it if true
/// </summary>
/// <param name = "_markupAutoLine">MarkupAutoLine</param>
/// <returns>boolean</returns>
public boolean avaMarkupAutoLinePurchLine(MarkupAutoLine _markupAutoLine)
{
    Common locCommon = this.parameters.Source;

    switch(locCommon.TableId)
    {
        case tableNum(PurchLine):
            PurchLine locPurchLine = locCommon as PurchLine;
            AgreementLine locALine = locPurchLine.avaGetAgreementLine();

            if(locALine.avaExistMarkup(true, _markupAutoLine.MarkupCategory))
            {
                return true;
            }
            break;
    }

    return false;
}
